    'daily' => __('Daily', RSR_TEXT_DOMAIN),
    'weekly' => __('Weekly', RSR_TEXT_DOMAIN),
    'monthly' => __('Monthly', RSR_TEXT_DOMAIN),
    'yearly' => __('Yearly', RSR_TEXT_DOMAIN),
];
get_header();
